import math
import hashlib
from typing import Any

class BloomFilter:
    def __init__(self, expected_items: int, fp_rate: float = 0.01):
        self.fp_rate = fp_rate
        self.size = self._optimal_size(expected_items, fp_rate)
        self.num_hashes = self._optimal_hashes(self.size, expected_items)
        self.bit_array = bytearray(math.ceil(self.size / 8))
        self.count = 0

    @staticmethod
    def _optimal_size(n: int, p: float) -> int:
        return int(-n * math.log(p) / (math.log(2) ** 2))

    @staticmethod
    def _optimal_hashes(m: int, n: int) -> int:
        return max(1, int((m / n) * math.log(2)))

    def _hashes(self, item: Any) -> list[int]:
        h1 = int(hashlib.sha256(str(item).encode()).hexdigest(), 16)
        h2 = int(hashlib.md5(str(item).encode()).hexdigest(), 16)
        return [(h1 + i * h2) % self.size for i in range(self.num_hashes)]

    def _set_bit(self, index: int):
        self.bit_array[index // 8] |= (1 << (index % 8))

    def _get_bit(self, index: int) -> bool:
        return bool(self.bit_array[index // 8] & (1 << (index % 8)))

    def add(self, item: Any):
        for idx in self._hashes(item):
            self._set_bit(idx)
        self.count += 1

    def __contains__(self, item: Any) -> bool:
        return all(self._get_bit(idx) for idx in self._hashes(item))

    def __len__(self) -> int:
        return self.count

    @property
    def estimated_fp_rate(self) -> float:
        bits_set = sum(bin(byte).count('1') for byte in self.bit_array)
        if bits_set == 0:
            return 0.0
        return (bits_set / self.size) ** self.num_hashes

