import socket
import select
import errno
from collections import defaultdict
from typing import Callable

class EventLoop:
    """Single-threaded event loop using epoll — same model as nginx/Redis."""

    READ = select.EPOLLIN
    WRITE = select.EPOLLOUT
    ERROR = select.EPOLLERR | select.EPOLLHUP

    def __init__(self):
        self.epoll = select.epoll()
        self.handlers: dict[int, dict[int, Callable]] = defaultdict(dict)
        self.sockets: dict[int, socket.socket] = {}
        self.running = False

    def register(self, sock: socket.socket, events: int, handler: Callable):
        fd = sock.fileno()
        self.sockets[fd] = sock
        self.handlers[fd][events] = handler
        mask = 0
        for ev in self.handlers[fd]:
            mask |= ev
        try:
            self.epoll.modify(fd, mask)
        except FileNotFoundError:
            self.epoll.register(fd, mask)

    def unregister(self, sock: socket.socket):
        fd = sock.fileno()
        try:
            self.epoll.unregister(fd)
        except (FileNotFoundError, OSError):
            pass
        self.handlers.pop(fd, None)
        self.sockets.pop(fd, None)

    def run(self):
        self.running = True
        while self.running:
            try:
                events = self.epoll.poll(timeout=1.0)
            except InterruptedError:
                continue

            for fd, event_mask in events:
                if fd not in self.handlers:
                    continue
                for registered_event, handler in list(self.handlers[fd].items()):
                    if event_mask & registered_event or event_mask & self.ERROR:
                        try:
                            handler(self.sockets.get(fd), event_mask)
                        except Exception as e:
                            print(f'Handler error on fd {fd}: {e}')
                            sock = self.sockets.get(fd)
                            if sock:
                                self.unregister(sock)
                                sock.close()

    def stop(self):
        self.running = False
        self.epoll.close()


class TCPServer:
    """High-performance TCP server built on epoll event loop."""

    def __init__(self, host: str = '0.0.0.0', port: int = 8080):
        self.host = host
        self.port = port
        self.loop = EventLoop()
        self.buffers: dict[int, bytearray] = defaultdict(bytearray)
        self.on_data: Callable[[socket.socket, bytes], bytes | None] = None

    def start(self):
        server_sock = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        server_sock.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
        server_sock.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEPORT, 1)
        server_sock.bind((self.host, self.port))
        server_sock.listen(4096)
        server_sock.setblocking(False)

        self.loop.register(server_sock, EventLoop.READ, self._on_accept)
        print(f'Listening on {self.host}:{self.port}')
        self.loop.run()

    def _on_accept(self, server_sock: socket.socket, events: int):
        while True:
            try:
                client, addr = server_sock.accept()
                client.setblocking(False)
                self.loop.register(client, EventLoop.READ, self._on_read)
            except BlockingIOError:
                break

    def _on_read(self, sock: socket.socket, events: int):
        if events & (EventLoop.ERROR):
            self._close(sock)
            return

        try:
            data = sock.recv(65536)
        except (BlockingIOError, ConnectionError):
            return

        if not data:
            self._close(sock)
            return

        if self.on_data:
            response = self.on_data(sock, data)
            if response:
                self.buffers[sock.fileno()] = bytearray(response)
                self.loop.register(sock, EventLoop.WRITE, self._on_write)

    def _on_write(self, sock: socket.socket, events: int):
        fd = sock.fileno()
        buf = self.buffers.get(fd, b'')
        if not buf:
            return

        try:
            sent = sock.send(buf)
            self.buffers[fd] = buf[sent:]
            if not self.buffers[fd]:
                del self.buffers[fd]
                # Re-register for read only
                self.loop.unregister(sock)
                self.loop.register(sock, EventLoop.READ, self._on_read)
        except BlockingIOError:
            pass
        except ConnectionError:
            self._close(sock)

    def _close(self, sock: socket.socket):
        fd = sock.fileno()
        self.buffers.pop(fd, None)
        self.loop.unregister(sock)
        sock.close()


