import hashlib
import bisect
from typing import Any

class ConsistentHash:
    """Consistent hashing ring with virtual nodes.

    When a node is added/removed, only K/N keys need to move (K=keys, N=nodes).
    Virtual nodes ensure even distribution — without them, nodes get uneven slices
    of the ring due to hash clustering.
    """

    def __init__(self, nodes: list[str] = None, replicas: int = 150):
        self.replicas = replicas  # Virtual nodes per real node
        self.ring: dict[int, str] = {}  # hash -> node name
        self.sorted_keys: list[int] = []  # Sorted hash positions
        self.nodes: set[str] = set()

        for node in (nodes or []):
            self.add_node(node)

    def _hash(self, key: str) -> int:
        return int(hashlib.md5(key.encode()).hexdigest(), 16)

    def add_node(self, node: str):
        """Add a node with its virtual nodes to the ring."""
        self.nodes.add(node)
        for i in range(self.replicas):
            virtual_key = f'{node}:vn{i}'
            h = self._hash(virtual_key)
            self.ring[h] = node
            bisect.insort(self.sorted_keys, h)

    def remove_node(self, node: str):
        """Remove a node and all its virtual nodes."""
        self.nodes.discard(node)
        for i in range(self.replicas):
            virtual_key = f'{node}:vn{i}'
            h = self._hash(virtual_key)
            if h in self.ring:
                del self.ring[h]
                self.sorted_keys.remove(h)

    def get_node(self, key: str) -> str:
        """Get the node responsible for this key."""
        if not self.ring:
            raise ValueError('No nodes in ring')

        h = self._hash(key)
        # Find the first node position >= key's hash
        idx = bisect.bisect_right(self.sorted_keys, h)
        # Wrap around to the first node if past the end
        if idx >= len(self.sorted_keys):
            idx = 0

        return self.ring[self.sorted_keys[idx]]

    def get_nodes(self, key: str, count: int = 3) -> list[str]:
        """Get N distinct nodes for replication."""
        if len(self.nodes) < count:
            count = len(self.nodes)

        h = self._hash(key)
        idx = bisect.bisect_right(self.sorted_keys, h)

        result = []
        seen = set()
        for i in range(len(self.sorted_keys)):
            pos = (idx + i) % len(self.sorted_keys)
            node = self.ring[self.sorted_keys[pos]]
            if node not in seen:
                result.append(node)
                seen.add(node)
                if len(result) == count:
                    break

        return result


class DistributedCache:
    """Distributed cache using consistent hashing."""

    def __init__(self, nodes: list[str], replicas: int = 150, replication: int = 2):
        self.ring = ConsistentHash(nodes, replicas)
        self.replication = replication
        # Simulate node storage (in reality these would be network calls)
        self.stores: dict[str, dict[str, Any]] = {node: {} for node in nodes}

    def put(self, key: str, value: Any):
        nodes = self.ring.get_nodes(key, self.replication)
        for node in nodes:
            self.stores[node][key] = value

    def get(self, key: str) -> Any:
        nodes = self.ring.get_nodes(key, self.replication)
        for node in nodes:
            if key in self.stores.get(node, {}):
                return self.stores[node][key]
        return None

    def add_node(self, node: str):
        self.ring.add_node(node)
        self.stores[node] = {}
        # In production: trigger key migration from neighboring nodes

    def remove_node(self, node: str):
        # Migrate data before removal
        data = self.stores.pop(node, {})
        self.ring.remove_node(node)
        # Re-insert migrated keys
        for key, value in data.items():
            self.put(key, value)

    def stats(self) -> dict[str, int]:
        return {node: len(store) for node, store in self.stores.items()}


# Demo
cache = DistributedCache(
    nodes=['redis-1:6379', 'redis-2:6379', 'redis-3:6379'],
    replication=2,
