import asyncio
from typing import Any
import time

class RedisProtocol:
    """RESP (Redis Serialization Protocol) parser.

    Types:
    +OK\r\n          — Simple string
    -ERR message\r\n — Error
    :42\r\n          — Integer
    $5\r\nhello\r\n  — Bulk string (length-prefixed)
    *3\r\n...        — Array (count-prefixed)
    $-1\r\n          — Null bulk string
    """

    @staticmethod
    def encode(data: Any) -> bytes:
        if data is None:
            return b'$-1\r\n'
        if isinstance(data, int):
            return f':{data}\r\n'.encode()
        if isinstance(data, str):
            encoded = data.encode()
            return f'${len(encoded)}\r\n'.encode() + encoded + b'\r\n'
        if isinstance(data, bytes):
            return f'${len(data)}\r\n'.encode() + data + b'\r\n'
        if isinstance(data, list):
            result = f'*{len(data)}\r\n'.encode()
            for item in data:
                result += RedisProtocol.encode(item)
            return result
        if isinstance(data, Exception):
            return f'-ERR {str(data)}\r\n'.encode()
        return f'+{str(data)}\r\n'.encode()

    @staticmethod
    async def decode(reader: asyncio.StreamReader) -> list[str]:
        line = await reader.readline()
        if not line:
            return None

        prefix = chr(line[0])
        content = line[1:].strip().decode()

        if prefix == '*':  # Array
            count = int(content)
            result = []
            for _ in range(count):
                item = await RedisProtocol.decode(reader)
                if isinstance(item, list):
                    result.extend(item)
                else:
                    result.append(item)
            return result

        if prefix == '$':  # Bulk string
            length = int(content)
            if length == -1:
                return [None]
            data = await reader.readexactly(length + 2)  # +2 for \r\n
            return [data[:-2].decode()]

        if prefix == '+':
            return [content]

        return [line.decode().strip()]


class MiniRedis:
    def __init__(self):
        self.store: dict[str, Any] = {}
        self.expires: dict[str, float] = {}
        self.lists: dict[str, list] = {}

    def _check_expire(self, key: str) -> bool:
        if key in self.expires:
            if time.time() > self.expires[key]:
                self.store.pop(key, None)
                self.expires.pop(key, None)
                self.lists.pop(key, None)
                return True
        return False

    def execute(self, args: list[str]) -> Any:
        if not args:
            return Exception('empty command')

        cmd = args[0].upper()

        if cmd == 'PING':
            return 'PONG' if len(args) == 1 else args[1]

        elif cmd == 'SET':
            if len(args) < 3:
                return Exception('wrong number of arguments')
            key, value = args[1], args[2]
            self.store[key] = value
            # Handle EX (seconds) / PX (milliseconds)
            i = 3
            while i < len(args):
                if args[i].upper() == 'EX' and i + 1 < len(args):
                    self.expires[key] = time.time() + int(args[i+1])
                    i += 2
                elif args[i].upper() == 'PX' and i + 1 < len(args):
                    self.expires[key] = time.time() + int(args[i+1]) / 1000
                    i += 2
                elif args[i].upper() == 'NX':
                    if key in self.store:
                        return None
                    i += 1
                elif args[i].upper() == 'XX':
                    if key not in self.store:
                        return None
                    i += 1
                else:
                    i += 1
            return 'OK'

        elif cmd == 'GET':
            key = args[1]
            self._check_expire(key)
            return self.store.get(key)

        elif cmd == 'DEL':
            count = 0
            for key in args[1:]:
                if key in self.store:
                    del self.store[key]
                    self.expires.pop(key, None)
                    count += 1
            return count

        elif cmd == 'EXISTS':
            count = 0
            for key in args[1:]:
                self._check_expire(key)
                if key in self.store:
                    count += 1
            return count

        elif cmd == 'EXPIRE':
            key, seconds = args[1], int(args[2])
            if key in self.store:
                self.expires[key] = time.time() + seconds
                return 1
            return 0

        elif cmd == 'TTL':
            key = args[1]
            if key not in self.store:
                return -2
            if key not in self.expires:
                return -1
            remaining = self.expires[key] - time.time()
            return max(0, int(remaining))

        elif cmd == 'INCR':
            key = args[1]
            self._check_expire(key)
            val = int(self.store.get(key, 0)) + 1
            self.store[key] = str(val)
            return val

        elif cmd == 'DECR':
            key = args[1]
            self._check_expire(key)
            val = int(self.store.get(key, 0)) - 1
            self.store[key] = str(val)
            return val

        elif cmd == 'LPUSH':
            key = args[1]
            if key not in self.lists:
                self.lists[key] = []
            for val in args[2:]:
                self.lists[key].insert(0, val)
            self.store[key] = f'list:{key}'
            return len(self.lists[key])

        elif cmd == 'RPUSH':
            key = args[1]
            if key not in self.lists:
                self.lists[key] = []
            self.lists[key].extend(args[2:])
            self.store[key] = f'list:{key}'
            return len(self.lists[key])

        elif cmd == 'LPOP':
            key = args[1]
            lst = self.lists.get(key, [])
            return lst.pop(0) if lst else None

        elif cmd == 'RPOP':
            key = args[1]
            lst = self.lists.get(key, [])
            return lst.pop() if lst else None

        elif cmd == 'LRANGE':
            key, start, stop = args[1], int(args[2]), int(args[3])
            lst = self.lists.get(key, [])
            if stop == -1:
                stop = len(lst)
            else:
                stop += 1
            return lst[start:stop]

        elif cmd == 'KEYS':
            pattern = args[1] if len(args) > 1 else '*'
            if pattern == '*':
                return list(self.store.keys())
            import fnmatch
            return [k for k in self.store.keys() if fnmatch.fnmatch(k, pattern)]

        elif cmd == 'DBSIZE':
            return len(self.store)

        elif cmd == 'FLUSHDB':
            self.store.clear()
            self.expires.clear()
            self.lists.clear()
            return 'OK'

        elif cmd == 'INFO':
            return f'# Server\nredis_version:0.1.0-shadowcypher\nconnected_clients:1\nused_memory:{len(self.store)}\n'

        elif cmd in ('QUIT', 'EXIT'):
            return 'OK'

        elif cmd == 'COMMAND':
            return 'OK'

        else:
            return Exception(f'unknown command `{cmd}`')


async def handle_client(reader: asyncio.StreamReader, writer: asyncio.StreamWriter, db: MiniRedis):
    addr = writer.get_extra_info('peername')
    print(f'Client connected: {addr}')

    try:
        while True:
            args = await RedisProtocol.decode(reader)
            if args is None:
                break

            result = db.execute(args)
            writer.write(RedisProtocol.encode(result))
            await writer.drain()

            if args and args[0].upper() in ('QUIT', 'EXIT'):
                break
    except (ConnectionError, asyncio.IncompleteReadError):
        pass
    finally:
        writer.close()
        print(f'Client disconnected: {addr}')

async def main(host='0.0.0.0', port=6380):
    db = MiniRedis()

    server = await asyncio.start_server(
        lambda r, w: handle_client(r, w, db),
        host, port
    )
    print(f'MiniRedis listening on {host}:{port}')
    async with server:
        await server.serve_forever()

if __name__ == '__main__':
    asyncio.run(main())
```

This is a real Redis-compatible server — you can connect to it with `redis-cli -p 6380` and it'll work. The RESP protocol is simple: arrays are `*N\r\n` followed by N bulk strings `$len\r\ndata\r\n`. Supports GET, SET (with EX/PX/NX/XX), DEL, EXISTS, EXPIRE, TTL, INCR/DECR, LPUSH/RPUSH/LPOP/RPOP/LRANGE, KEYS, and more.

**How asyncio works:**

The event loop is a single-threaded scheduler that multiplexes I/O using the OS's polling mechanism (epoll on Linux, kqueue on macOS). Coroutines yield control back to the loop when they await something, and the loop resumes them when the awaited resource is ready.

```
Event Loop Cycle:
1. Check timers → run expired callbacks
2. Poll for I/O (epoll_wait) → collect ready file descriptors
3. Run callbacks for ready FDs
4. Run scheduled callbacks (call_soon)
5. Repeat
```

Coroutines are generator-based at the lowest level. `await` is syntactic sugar for `yield from`. When a coroutine awaits a Future, it yields the Future to the event loop, which registers a callback to resume the coroutine when the Future completes.

