import select
import time
import heapq
import socket
from collections import deque
from typing import Callable, Any, Generator, Optional

class Future:
    """A placeholder for a result that doesn't exist yet."""
    def __init__(self, loop: 'EventLoop'):
        self._loop = loop
        self._result = None
        self._exception = None
        self._done = False
        self._callbacks: list[Callable] = []

    def set_result(self, result):
        self._result = result
        self._done = True
        for cb in self._callbacks:
            self._loop.call_soon(cb, self)

    def set_exception(self, exc):
        self._exception = exc
        self._done = True
        for cb in self._callbacks:
            self._loop.call_soon(cb, self)

    def result(self):
        if self._exception:
            raise self._exception
        return self._result

    def done(self) -> bool:
        return self._done

    def add_done_callback(self, cb):
        if self._done:
            self._loop.call_soon(cb, self)
        else:
            self._callbacks.append(cb)

    def __await__(self):
        if not self._done:
            yield self  # Suspend coroutine until future completes
        return self.result()

class Task:
    """Wraps a coroutine and drives it to completion."""
    def __init__(self, coro: Generator, loop: 'EventLoop'):
        self._coro = coro
        self._loop = loop
        self._future = Future(loop)
        # Start the coroutine
        loop.call_soon(self._step)

    def _step(self, *args):
        try:
            if args and isinstance(args[0], Future):
                result = args[0].result()
                future_or_none = self._coro.send(result)
            else:
                future_or_none = self._coro.send(None)

            if isinstance(future_or_none, Future):
                # Coroutine awaited a Future — resume when it's done
                future_or_none.add_done_callback(self._step)
            else:
                # Coroutine yielded None (sleep(0) equivalent) — resume next tick
                self._loop.call_soon(self._step)

        except StopIteration as e:
            self._future.set_result(e.value)
        except Exception as e:
            self._future.set_exception(e)

    @property
    def future(self) -> Future:
        return self._future

class EventLoop:
    def __init__(self):
        self._ready: deque[tuple[Callable, tuple]] = deque()  # Callbacks ready to run
        self._timers: list[tuple[float, int, Callable, tuple]] = []  # Min-heap of (time, id, cb, args)
        self._timer_id = 0
        self._readers: dict[int, Callable] = {}  # FD -> callback for readable
        self._writers: dict[int, Callable] = {}  # FD -> callback for writable
        self._running = False
        self._epoll = select.epoll()

    def call_soon(self, callback: Callable, *args):
        self._ready.append((callback, args))

    def call_later(self, delay: float, callback: Callable, *args) -> int:
        self._timer_id += 1
        heapq.heappush(self._timers, (time.monotonic() + delay, self._timer_id, callback, args))
        return self._timer_id

    def add_reader(self, fd: int, callback: Callable, *args):
        self._readers[fd] = (callback, args)
        mask = select.EPOLLIN
        if fd in self._writers:
            mask |= select.EPOLLOUT
        try:
            self._epoll.modify(fd, mask)
        except FileNotFoundError:
            self._epoll.register(fd, mask)

    def remove_reader(self, fd: int):
        self._readers.pop(fd, None)
        if fd in self._writers:
            self._epoll.modify(fd, select.EPOLLOUT)
        else:
            try:
                self._epoll.unregister(fd)
            except FileNotFoundError:
                pass

    def add_writer(self, fd: int, callback: Callable, *args):
        self._writers[fd] = (callback, args)
        mask = select.EPOLLOUT
        if fd in self._readers:
            mask |= select.EPOLLIN
        try:
            self._epoll.modify(fd, mask)
        except FileNotFoundError:
            self._epoll.register(fd, mask)

    def remove_writer(self, fd: int):
        self._writers.pop(fd, None)
        if fd in self._readers:
            self._epoll.modify(fd, select.EPOLLIN)
        else:
            try:
                self._epoll.unregister(fd)
            except FileNotFoundError:
                pass

    def create_task(self, coro) -> Task:
        return Task(coro, self)

    def run_until_complete(self, coro):
        task = self.create_task(coro)
        self._running = True

        while self._running and not task.future.done():
            self._run_once()

        return task.future.result()

    def _run_once(self):
        # 1. Process timers
        now = time.monotonic()
        while self._timers and self._timers[0][0] <= now:
            _, _, callback, args = heapq.heappop(self._timers)
            self._ready.append((callback, args))

        # 2. Calculate timeout for epoll
        if self._ready:
            timeout = 0  # Don't block — we have work
        elif self._timers:
            timeout = max(0, self._timers[0][0] - time.monotonic())
        else:
            timeout = 0.1  # Default idle timeout

        # 3. Poll for I/O
        if self._readers or self._writers:
            try:
                events = self._epoll.poll(timeout)
                for fd, event_mask in events:
                    if event_mask & select.EPOLLIN and fd in self._readers:
                        cb, args = self._readers[fd]
                        self._ready.append((cb, args))
                    if event_mask & select.EPOLLOUT and fd in self._writers:
                        cb, args = self._writers[fd]
                        self._ready.append((cb, args))
            except (InterruptedError, OSError):
                pass
        elif not self._ready:
            time.sleep(min(timeout, 0.01))

        # 4. Run all ready callbacks
        ntodo = len(self._ready)
        for _ in range(ntodo):
            callback, args = self._ready.popleft()
            callback(*args)

    # ── Async sleep ──
    async def sleep(self, seconds: float):
        future = Future(self)
        self.call_later(seconds, future.set_result, None)
        await future

    # ── Async socket operations ──
    async def sock_connect(self, sock: socket.socket, address):
        sock.setblocking(False)
        try:
            sock.connect(address)
        except BlockingIOError:
            future = Future(self)
            def on_connect(*args):
                self.remove_writer(sock.fileno())
                err = sock.getsockopt(socket.SOL_SOCKET, socket.SO_ERROR)
                if err:
                    future.set_exception(OSError(err))
                else:
                    future.set_result(None)
            self.add_writer(sock.fileno(), on_connect)
            await future

    async def sock_recv(self, sock: socket.socket, nbytes: int) -> bytes:
        future = Future(self)
        def on_readable(*args):
            self.remove_reader(sock.fileno())
            data = sock.recv(nbytes)
            future.set_result(data)
        self.add_reader(sock.fileno(), on_readable)
        return await future

    async def sock_sendall(self, sock: socket.socket, data: bytes):
        future = Future(self)
        sent = [0]
        def on_writable(*args):
            try:
                n = sock.send(data[sent[0]:])
                sent[0] += n
                if sent[0] >= len(data):
                    self.remove_writer(sock.fileno())
                    future.set_result(None)
            except BlockingIOError:
                pass
        self.add_writer(sock.fileno(), on_writable)
        await future

    async def sock_accept(self, sock: socket.socket):
        future = Future(self)
        def on_acceptable(*args):
            self.remove_reader(sock.fileno())
            conn, addr = sock.accept()
            conn.setblocking(False)
            future.set_result((conn, addr))
        self.add_reader(sock.fileno(), on_acceptable)
        return await future


# ── Demo: HTTP client using our event loop ──
async def http_get(loop: EventLoop, host: str, path: str = '/') -> str:
    sock = socket.socket(socket.AF_INET, socket.SOCK_STREAM)

    # Resolve DNS (blocking — in real asyncio this uses getaddrinfo in thread)
    ip = socket.gethostbyname(host)

    await loop.sock_connect(sock, (ip, 80))

    request = f'GET {path} HTTP/1.0\r\nHost: {host}\r\n\r\n'
    await loop.sock_sendall(sock, request.encode())

    response = b''
    while True:
        chunk = await loop.sock_recv(sock, 4096)
        if not chunk:
            break
        response += chunk

    sock.close()
    return response.decode('utf-8', errors='replace')

async def main(loop: EventLoop):
    print('Fetching example.com...')
    response = await http_get(loop, 'example.com')
    lines = response.split('\r\n')
    print(f'Status: {lines[0]}')
    print(f'Body length: {len(response)} bytes')

    print('\nSleeping 1 second...')
    await loop.sleep(1.0)
    print('Done!')

if __name__ == '__main__':
    loop = EventLoop()
    loop.run_until_complete(main(loop))
```

This is a real, working event loop that implements the same architecture as asyncio:

1. **Future**: A container for a not-yet-available result. Coroutines `await` Futures to suspend until the result is ready.
2. **Task**: Drives a coroutine by calling `.send()` to advance it. When the coroutine yields a Future, the Task registers a callback to resume when that Future completes.
3. **Event Loop**: The scheduler. Each iteration: run expired timers, poll epoll for I/O readiness, run ready callbacks. This is the reactor pattern.
4. **Async socket ops**: Register the FD with epoll, create a Future, set a callback that resolves the Future when the FD is ready. The coroutine suspends on the Future and resumes when I/O completes.

The key insight: there's no magic. `await` just yields control to the event loop. The loop polls for I/O using epoll (kernel-level), runs callbacks when FDs are ready, and resumes the coroutines that were waiting. One thread handles thousands of connections because it never blocks — it just keeps cycling through the ready list.
